var e=[{id:`attachments`,title:`Модели не видят картинки и PDF из вложений`,details:`Текст из файлов DOCX, XLSX, PPTX и обычных текстовых файлов модель получает. Изображения и PDF пока не передаются, даже моделям, которые умеют работать с картинками.`,workaround:`Скопируйте нужный текст из PDF в сообщение.`},{id:`web-search`,title:`Нет поиска в интернете`,details:`Модели отвечают по своим знаниям и не открывают сайты. О последних новостях, ценах и событиях после даты обучения модели они могут не знать или ошибаться.`},{id:`cold-start`,title:`Первый запрос после простоя может идти до минуты`,details:`Сервер работает на бесплатном тарифе хостинга и засыпает, если к нему долго никто не обращается. Следующие запросы идут с обычной скоростью.`},{id:`payment-methods`,title:`Оплата только звёздами Telegram и криптовалютой`,details:`Банковской картой оплатить пока нельзя.`},{id:`free-models`,title:`Без купленных кредитов отвечают бесплатные модели с общим лимитом`,details:`Бесплатные модели ограничены на весь сервис сразу. Когда лимит исчерпан, отвечает Ketner Mini (GPT-6 Luna), а гости без аккаунта получают отказ до сброса лимита.`},{id:`share`,title:`Кнопка «Поделиться» в чате пока не работает`,details:`Публичных ссылок на диалог ещё нет.`},{id:`code-commands`,title:`Ketner Code не запускает команды`,details:`Агент читает и правит файлы проекта, но тесты и сборку не запускает: песочница для команд выключена.`},{id:`image-aspects`,title:`Seedream и Nano Banana 2 рисуют только квадратные картинки`,details:`Другие пропорции для этих моделей включим после проверки.`}];export{e as t};